"""Local report presentation; no dependencies or network requests."""

STYLE = r'''
:root{color-scheme:light;--ink:#172b44;--muted:#607087;--line:#dde5ee;--blue:#245ac2;--paper:#fff;--soft:#f1f5fb}
*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:var(--ink);font:15px/1.7 system-ui,"Microsoft YaHei",sans-serif}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}button,input,select{font:inherit}button,summary,select{cursor:pointer}:focus-visible{outline:3px solid #78a8ff;outline-offset:3px}[hidden]{display:none!important}
.shell{max-width:1180px;margin:auto;padding:28px 32px}.skip-link{position:absolute;left:16px;top:-80px;background:white;padding:10px;z-index:5}.skip-link:focus{top:10px}.site-header{background:var(--paper);border-bottom:1px solid var(--line)}.header-inner{max-width:1180px;margin:auto;padding:18px 32px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{font-size:18px;font-weight:750;color:var(--ink)}.brand small{display:block;color:var(--muted);font-size:12px;font-weight:400}.report-nav{display:flex;flex-wrap:wrap;gap:6px}.report-nav a{padding:8px 16px;border-radius:9px;color:var(--muted);font-weight:600}.report-nav a[aria-current]{background:#eaf1ff;color:var(--blue)}h1{font-size:28px;line-height:1.4;margin:0 0 8px;letter-spacing:-.5px}.page-intro{max-width:780px;color:var(--muted);margin:0 0 22px}.page-heading{margin-bottom:18px}.page-total{font-size:13px;color:var(--muted)}
.queues{display:flex;gap:6px;flex-wrap:wrap;margin:18px 0}.queues button{border:1px solid transparent;background:transparent;color:var(--muted);border-radius:9px;padding:9px 16px;font-weight:600}.queues button[aria-pressed=true]{background:var(--ink);color:white}.queues .queue-count{display:inline-block;min-width:24px;border-radius:5px;padding:0 5px;margin-left:8px;font-size:12px;background:#ffffff25}.toolbar{background:white;border:1px solid var(--line);padding:18px;border-radius:13px;margin-bottom:20px}.search-row{display:flex;align-items:center;gap:12px}.search-label{flex:1;display:flex;align-items:center;gap:10px;min-width:180px;color:var(--muted)}input[type=search]{width:100%;min-width:100px;border:1px solid var(--line);border-radius:8px;padding:10px 13px;background:#f8fafc;color:var(--ink)}.filters{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:12px}.filters label{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--muted)}select{max-width:320px;border:1px solid var(--line);border-radius:7px;padding:7px 26px 7px 9px;color:var(--ink);background:white}.more-filters summary{color:var(--blue);font-size:13px}.more-filters>div{display:flex;gap:12px;flex-wrap:wrap;margin-top:10px}.clear-button,.pager button{border:1px solid var(--line);background:white;border-radius:7px;padding:7px 12px;color:var(--muted)}.clear-button:hover,.pager button:hover:enabled{border-color:var(--blue);color:var(--blue)}.screen-reader{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.result-line{display:flex;justify-content:space-between;align-items:center;color:var(--muted);font-size:13px;margin:0 0 12px}.pager{display:flex;justify-content:center;align-items:center;gap:16px;margin:24px 0}.pager button:disabled{opacity:.4;cursor:default}
main{scroll-margin-top:180px;display:grid;grid-template-columns:minmax(0,1fr);gap:14px}article{background:white;border:1px solid var(--line);border-radius:12px;padding:22px 24px;min-width:0}article:hover{border-color:#b9cce4}article h2{font-size:18px;line-height:1.55;margin:0 0 7px;overflow-wrap:anywhere}article[data-lane=followup]{border-left:3px solid #d89a35}article[data-lane=archive]{background:#f9fafc;border-left:3px solid #a1aebf}article p.meta{color:var(--muted);font-size:12px;margin:6px 0 10px}article pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.8;margin:9px 0}article details{border-top:1px solid #edf1f6;margin-top:14px;padding-top:11px}article details details{margin-left:8px}summary{color:var(--blue);font-size:14px;padding:2px 0}article section{margin-top:12px;padding:8px 14px;border-left:2px solid #dce6f5}article section+section{border-top:1px solid #edf1f6}article ul{padding-left:22px}.card-excerpt{color:#42556d;white-space:pre-wrap;overflow-wrap:anywhere;margin:10px 0;font-size:14px}.card-detail-grid{margin:8px 0}.empty{grid-column:1/-1;padding:44px 24px;text-align:center;background:white;border:1px dashed #c5d1e0;border-radius:12px;color:var(--muted)}.empty strong{display:block;color:var(--ink);font-size:18px;margin-bottom:8px}.empty p{margin:6px 0}.coverage-banner{max-width:1116px;margin:18px auto!important;font-size:12px;line-height:1.9}.coverage-banner nav{margin-top:8px}.coverage-banner nav a{margin-right:10px}footer{color:var(--muted);font-size:12px;padding:24px 0;border-top:1px solid var(--line);margin-top:30px}.back-top{float:right}button{max-width:100%}
@media(min-width:1250px){.toolbar{position:sticky;top:12px;z-index:2;box-shadow:0 4px 18px #142d4d08}}
@media(max-width:700px){.shell{padding:20px 14px}.header-inner{padding:14px;display:block}.report-nav{margin-top:12px}.report-nav a{padding:7px 12px}.brand small{display:none}h1{font-size:24px}.search-row{align-items:stretch;flex-wrap:wrap}.search-label{width:100%}.search-label>span{display:none}.filters{gap:10px}.filters select{max-width:230px}.queues{gap:2px}.queues button{padding:8px 11px}article{padding:17px 16px}article h2{font-size:17px}.coverage-banner{margin:12px 14px!important}.result-line{align-items:flex-start;gap:10px}}
'''

SCRIPT = r'''
const group=document.getElementById('group'),search=document.getElementById('search');
let currentPage=1;const pageSize=20;
function filterRows(resetPage=true){
 if(resetPage)currentPage=1;
 const g=group.value,q=search.value.toLocaleLowerCase(),v=document.getElementById('value')?.value||'',s=document.getElementById('term-status')?.value||'',c=document.getElementById('category')?.value||'',k=document.getElementById('term-kind')?.value||'',lane=document.getElementById('lane')?.value||'',topic=document.getElementById('topic')?.value||'';
 let count=0;const matched=[];
 document.querySelectorAll('article').forEach(card=>{
  const category=card.dataset.category||'knowledge',topics=(card.dataset.topics||'').split(','),base=!(g&&card.dataset.group!==g)&&!(v&&card.dataset.value!==v)&&!(c==='durable'&&category==='transient')&&!(c&&c!=='durable'&&category!==c)&&!(lane&&card.dataset.lane!==lane)&&!(topic&&!topics.includes(topic)),variants=card.querySelectorAll?.('[data-term-variant]')||[];
  if(variants.length){let any=false;const shared=(card.dataset.termShared||'').toLocaleLowerCase();variants.forEach(item=>{
   const matchesSearch=!q||shared.includes(q)||(item.textContent||'').toLocaleLowerCase().includes(q);
   item.hidden=!(base&&matchesSearch&&(!s||(item.dataset.status===s||item.dataset.origin===s))&&(!k||item.dataset.inference===k));if(!item.hidden)any=true;
  });card.hidden=!any;}else{card.hidden=!(base&&card.textContent.toLocaleLowerCase().includes(q)&&(!s||(card.dataset.status===s||card.dataset.origin===s))&&(!k||card.dataset.inference===k));}
  if(!card.hidden){count++;matched.push(card);}
 });
 document.getElementById('filter-empty').hidden=count>0;
 const shown=document.getElementById('shown-count');if(shown)shown.textContent=count;
 const pager=document.getElementById('page-info');
 if(pager){const pages=Math.max(1,Math.ceil(count/pageSize));currentPage=Math.min(Math.max(1,currentPage),pages);matched.forEach((card,i)=>card.hidden=i<(currentPage-1)*pageSize||i>=currentPage*pageSize);pager.textContent=count?`${currentPage} / ${pages} 页`:'0 / 0 页';document.getElementById('previous-page').disabled=currentPage<=1;document.getElementById('next-page').disabled=currentPage>=pages;}
 document.querySelectorAll('[data-lane-target]').forEach(button=>{if(button.dataset.laneTarget===undefined)return;button.setAttribute?.('aria-pressed',String(button.dataset.laneTarget===lane));});
}
group.addEventListener('change',()=>filterRows());search.addEventListener('input',()=>filterRows());
['value','term-status','category','term-kind','lane','topic'].forEach(id=>document.getElementById(id)?.addEventListener('change',()=>filterRows()));
document.getElementById('clear-filters')?.addEventListener('click',()=>{search.value='';group.value='';['value','term-status','category','term-kind','topic'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});filterRows();search.focus();});
document.querySelectorAll('[data-lane-target]').forEach(button=>{if(button.dataset.laneTarget===undefined)return;button.addEventListener('click',()=>{const lane=document.getElementById('lane');if(lane){lane.value=button.dataset.laneTarget;filterRows();if(typeof window!=='undefined')window.location.hash=lane.value||'all';}});});
document.getElementById('previous-page')?.addEventListener('click',()=>{currentPage--;filterRows(false);document.getElementById('results')?.scrollIntoView({block:'start'});});
document.getElementById('next-page')?.addEventListener('click',()=>{currentPage++;filterRows(false);document.getElementById('results')?.scrollIntoView({block:'start'});});
if(typeof window!=='undefined'){
 const applyHash=()=>{const lane=document.getElementById('lane'),hash=window.location.hash.slice(1);if(lane&&['','knowledge','followup','archive','all'].includes(hash)){lane.value=hash==='all'?'':hash||'knowledge';filterRows();}};
 window.addEventListener('hashchange',applyHash);applyHash();
 document.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key==='k'){event.preventDefault();search.focus();}});
}
filterRows();
'''
